'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple factory has an `of` method', function test( t ) {
	var Point;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	t.strictEqual( hasOwnProp( Point, 'of' ), true, 'returns expected value' );
	t.strictEqual( isFunction( Point.of ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not the host tuple factory', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Point.of.call( value, 1, 2 );
		};
	}
});

tape( 'the method throws a range error if the number of arguments is incompatible with the number of tuple fields', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		[],
		[ 1 ],
		[ 1, 2, 3 ],
		[ 1, 2, 3, 4 ]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided an array of length '+values[ i ].length );
	}
	t.end();

	function badValue( args ) {
		return function badValue() {
			return Point.of.apply( Point, args );
		};
	}
});

tape( 'the method creates a new tuple from a variable number of arguments', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.of( 10, 20, 30 );

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 20, 'returns expected value' );
	t.strictEqual( p[ 2 ], 30, 'returns expected value' );
	t.deepEqual( p.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();
});
